{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Bath Events</title>
  <meta name="description" content="Immersive sound experiences for recalibration and clarity. Small groups, private sessions, and seasonal intensives.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="site">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="8" fill="url(#g)"/></svg>
      <div class="brand-text">
        <strong class="name">{{BUSINESS_NAME}}</strong>
        <small class="tag">Gentle sound-led immersion • {{CITY}}, {{STATE}}</small>
      </div>
    </div>
    <nav class="nav">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">The Space</a>
      <a href="faq.html">FAQ</a>
      <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
    <button class="mobile-toggle" aria-label="Toggle navigation">☰</button>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <svg class="hero-pattern" viewBox="0 0 800 200" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          <pattern id="p" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
            <path d="M0 20 C10 10,30 30,40 20" stroke="#1a1a2e" stroke-opacity="0.06" fill="none" stroke-width="2"/>
          </pattern>
        </defs>
        <rect width="800" height="200" fill="url(#p)"/>
      </svg>
      <div class="hero-inner">
        <h1 class="title">Sound-led intensives for clearer rest and renewed attention</h1>
        <p class="lede">Join intimate sessions and focused weekends that use tuned sound, breath orientation, and guided stillness to help you step back into daily clarity.</p>
        <div class="hero-actions">
          <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="secondary" href="events.html">See upcoming gatherings</a>
        </div>
        <p class="contact-small">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">email us</a>.</p>
      </div>
    </section>

    <!-- QUICK OFFER / OFFERS -->
    <section class="offers" id="offers">
      <h2 class="section-title">Programs & Pathways</h2>
      <div class="offer-cards">
        <article class="card">
          <h3>Grounding Gatherings</h3>
          <p>Weekly small-group sound sessions oriented to steadying the nervous system. 60 minutes, limited seating.</p>
          <div class="card-actions">
            <a href="events.html">Upcoming dates</a>
            <a href="book.html" class="muted">Reserve a spot</a>
          </div>
        </article>
        <article class="card">
          <h3>Deep Cycle Intensive</h3>
          <p>A concentrated weekend retreat with layered sound practices and guided integration work. Ideal for those seeking deeper recalibration.</p>
          <div class="card-actions">
            <a href="book.html">Inquire</a>
            <a href="pricing.html" class="muted">Details & rates</a>
          </div>
        </article>
        <article class="card">
          <h3>Private Sessions</h3>
          <p>One-on-one sessions tailored to your body, breath, and listening needs. Flexible length and focused support.</p>
          <div class="card-actions">
            <a href="private-sessions.html">Learn more</a>
            <a href="book.html" class="muted">Book</a>
          </div>
        </article>
      </div>
    </section>

    <!-- FRAMEWORK / METHOD -->
    <section class="framework" id="framework">
      <h2 class="section-title">Our Approach</h2>
      <p class="framework-lede">We combine tuned instruments, breath orientation, and gentle guidance so each session becomes a reliable container for rest and attention.</p>
      <ul class="pillars">
        <li><strong>Anchor</strong><span>Breath-led settling and posture alignment</span></li>
        <li><strong>Tone</strong><span>Layered instruments tuned to support resonance</span></li>
        <li><strong>Integration</strong><span>Short reflection and movement to return to everyday life</span></li>
      </ul>
      <p class="note">Contraindications: Sound immersion can be intense. Please consult your healthcare provider if you have epilepsy, recent head injury, active psychosis, or are pregnant. Tell us about implants or devices that may be sensitive to vibration.</p>
    </section>

    <!-- PRICING COMPARATOR -->
    <section class="pricing" id="pricing">
      <h2 class="section-title">Rates</h2>
      <div class="pricing-controls">
        <label class="toggle">
          <input type="checkbox" id="billingToggle">
          <span class="labels">Monthly <em>vs</em> Package</span>
        </label>
        <div class="price-display" aria-live="polite">
          <div class="price-item">
            <div class="price-amount" data-monthly="25" data-package="220">$<span class="num">25</span></div>
            <div class="price-desc">Drop-in / Monthly pass</div>
          </div>
          <div class="price-item">
            <div class="price-amount" data-monthly="75" data-package="640">$<span class="num">75</span></div>
            <div class="price-desc">Private session</div>
          </div>
        </div>
      </div>
      <p class="pricing-note">Switch to see per-class breakdowns and package savings. Prices animate when toggled.</p>
    </section>

    <!-- PROOF GALLERY: rotating testimonials + badges -->
    <section class="testimonials" id="testimonials">
      <h2 class="section-title">Voices from the room</h2>
      <div class="proof">
        <div class="testimonial-rotator" id="testimonialRotator" aria-live="polite">
          <blockquote class="quote">"The session peeled away the day's fog — I left steady and more present."<footer>— A. · Attendee</footer></blockquote>
          <blockquote class="quote hidden">"Small group, huge clarity. The sound made room for thinking differently."<footer>— B. · Participant</footer></blockquote>
          <blockquote class="quote hidden">"After a private session I slept through the night for the first time in months."<footer>— C. · Private client</footer></blockquote>
        </div>
        <div class="badges" id="credBadges">
          <div class="badge" data-tip="Featured in Local Health Journal">Local Health Journal</div>
          <div class="badge" data-tip="Trusted by community studios">Community Studios</div>
          <div class="badge" data-tip="Practitioner-led, accredited facilitators">Accredited Facilitators</div>
        </div>
      </div>
    </section>

    <!-- NEXT EVENT MODULE (preview of Events page) -->
    <section class="next-event" id="nextEvent">
      <h2 class="section-title">Next Gathering</h2>
      <div class="next-card">
        <div class="event-meta">
          <div class="date">Sat • Mar 14</div>
          <div class="time">10:00 — 11:15</div>
        </div>
        <div class="event-body">
          <h3>Morning Grounding: Small Group</h3>
          <p>Soft bells, crystal and metal tones, guided breath to ground and re-orient. Capacity limited to 12.</p>
          <div class="event-actions">
            <a href="events.html">View calendar</a>
            <a href="book.html" class="primary">Reserve a spot</a>
          </div>
        </div>
      </div>

      <div class="calendar-list" aria-hidden="false">
        <h4>Coming weeks</h4>
        <ul>
          <li>Mar 14 — Morning Grounding</li>
          <li>Mar 21 — Evening Reset</li>
          <li>Apr 4 — Deep Cycle Intensive (Weekend)</li>
          <li>Apr 18 — Private Sessions available</li>
        </ul>
      </div>
    </section>

    <!-- CTA / BOOK -->
    <section class="cta" id="finalCta">
      <h2>Ready to try a focused sound session?</h2>
      <p>Request a spot, ask a question, or check availability for a private session.</p>
      <a class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
      <div>
        <nav class="foot-nav">
          <a href="about.html">The Space</a>
          <a href="pricing.html">Rates</a>
          <a href="faq.html">FAQ</a>
        </nav>
      </div>
      <div>
        <p>Office: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p><a href="privacy.html">Privacy</a></p>
      </div>
    </div>
    <small class="copyright">© <span id="year">2026</span> {{BUSINESS_NAME}}</small>
  </footer>

  <!-- assets/img/pattern.svg used as background in CSS -->
</body>
</html>"} 
