{"path":"assets/css/styles.css","content":"/* Base styles - bold_playful + mystic_modern */
:root{
  --bg:#fbfcff;
  --accent:#2b2d6e;
  --muted:#6b7280;
  --glass:rgba(255,255,255,0.6);
  --card:#ffffff;
  --radius:12px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; margin:0; color:#0b1220; background:var(--bg); -webkit-font-smoothing:antialiased}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;border-bottom:1px solid rgba(10,12,20,0.04);position:sticky;top:0;background:linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.6));backdrop-filter:blur(6px);z-index:40}
.brand{display:flex;gap:12px;align-items:center}
.brand .logo{background:linear-gradient(135deg,#dbeafe,#f0f9ff);border-radius:8px}
.brand-text .name{display:block;font-size:16px}
.brand-text .tag{color:var(--muted);font-size:12px}
.nav{display:flex;gap:14px;align-items:center}
.nav a{color:var(--accent);text-decoration:none;padding:8px 10px;border-radius:8px;font-weight:600}
.nav a.cta{background:var(--accent);color:#fff;padding:8px 12px}
.mobile-toggle{display:none;background:none;border:0;font-size:20px}

.hero{position:relative;padding:44px 28px 28px;overflow:hidden}
.hero-pattern{position:absolute;left:0;top:0;width:100%;height:100%;opacity:0.12}
.hero-inner{max-width:980px;margin:0 auto;position:relative}
.title{font-size:32px;margin:0 0 12px;color:var(--accent)}
.lede{margin:0 0 18px;color:var(--muted)}
.hero-actions{display:flex;gap:12px}
.primary{display:inline-block;background:var(--accent);color:#fff;padding:10px 16px;border-radius:10px;text-decoration:none}
.secondary{display:inline-block;color:var(--accent);padding:8px 12px;text-decoration:none}
.contact-small{color:var(--muted);margin-top:12px}

.section-title{font-size:18px;color:var(--accent);margin:28px auto 12px;max-width:980px}
.offers{max-width:980px;margin:0 auto;padding:6px 28px}
.offer-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
.card{background:var(--card);padding:14px;border-radius:var(--radius);box-shadow:0 6px 18px rgba(11,16,28,0.04)}
.card h3{margin:0 0 6px}
.card p{color:var(--muted);margin:0 0 12px;font-size:14px}
.card-actions a{margin-right:8px;color:var(--accent);text-decoration:none}
.card-actions a.muted{color:var(--muted)}

.framework{max-width:980px;margin:18px auto;padding:0 28px}
.framework-lede{color:var(--muted)}
.pillars{display:flex;gap:12px;list-style:none;padding:0;margin:12px 0}
.pillars li{background:linear-gradient(180deg,#fff,#f7fbff);padding:10px;border-radius:10px;flex:1}
.pillars li strong{display:block}
.note{font-size:13px;color:#8b2f2f;background:#fff6f6;padding:10px;border-radius:8px;margin-top:8px}

.pricing{max-width:980px;margin:18px auto;padding:0 28px}
.pricing-controls{display:flex;gap:18px;align-items:center}
.toggle{display:flex;align-items:center;gap:8px}
.toggle input{width:40px;height:22px;appearance:none;background:#e6e7f3;border-radius:999px;position:relative;outline:none}
.toggle input:checked{background:var(--accent)}
.toggle input:before{content:"";position:absolute;width:18px;height:18px;background:#fff;border-radius:50%;top:2px;left:2px;transition:transform .28s}
.toggle input:checked:before{transform:translateX(18px)}
.price-display{display:flex;gap:18px}
.price-item{background:var(--card);padding:12px;border-radius:12px;min-width:140px;text-align:center}
.price-amount{font-size:20px;color:var(--accent)}
.num{display:inline-block;min-width:36px;text-align:right}
.pricing-note{color:var(--muted);font-size:13px}

.testimonials{max-width:980px;margin:18px auto;padding:0 28px}
.proof{display:flex;gap:18px;align-items:start}
.testimonial-rotator{flex:1;position:relative}
.quote{background:linear-gradient(180deg,#ffffff,#fcfeff);padding:16px;border-radius:12px;box-shadow:0 6px 16px rgba(10,12,20,0.04)}
.quote.hidden{display:none}
.quote footer{margin-top:8px;color:var(--muted);font-size:13px}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:var(--card);padding:8px 10px;border-radius:8px;color:var(--muted);font-weight:600;border:1px solid rgba(10,12,20,0.04);position:relative}
.badge:hover{cursor:default}
.badge .tip{position:absolute;left:110%;top:50%;transform:translateY(-50%);background:#111827;color:#fff;padding:8px;border-radius:8px;white-space:nowrap;display:none}
.badge[data-show-tip="true"] .tip{display:block}

.next-event{max-width:980px;margin:18px auto;padding:0 28px}
.next-card{display:flex;gap:12px;background:var(--card);padding:12px;border-radius:12px}
.event-meta{width:108px;background:linear-gradient(180deg,#eef2ff,#ffffff);padding:10px;border-radius:8px;text-align:center}
.event-body h3{margin:0 0 6px}
.event-actions a{margin-right:8px}

.cta{max-width:980px;margin:28px auto;padding:18px 28px;text-align:center;background:linear-gradient(180deg,#fff,#fbfdff);border-radius:14px}
.primary.large{font-size:16px;padding:12px 20px}

.site-footer{border-top:1px solid rgba(10,12,20,0.04);padding:20px 28px;margin-top:18px}
.footer-grid{display:flex;gap:24px;justify-content:space-between}
.foot-nav a{display:block;color:var(--muted);text-decoration:none}

@media (max-width:900px){
  .nav{display:none}
  .mobile-toggle{display:inline-block}
  .pillars{flex-direction:column}
  .proof{flex-direction:column}
  .footer-grid{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"// Main JS: rotates testimonials, badge tooltips, pricing toggle animation, mobile nav
document.addEventListener('DOMContentLoaded',function(){
  // Mobile nav
  var toggle = document.querySelector('.mobile-toggle');
  if(toggle){
    toggle.addEventListener('click',function(){
      var nav = document.querySelector('.nav');
      if(nav.style.display === 'flex'){nav.style.display='none'} else {nav.style.display='flex';nav.style.flexDirection='column'}
    });
  }

  // Testimonial rotator
  (function(){
    var rotator = document.getElementById('testimonialRotator');
    if(!rotator) return;
    var quotes = Array.from(rotator.querySelectorAll('.quote'));
    var idx = 0;
    function show(i){
      quotes.forEach(function(q,ii){
        q.classList.toggle('hidden', ii!==i);
      });
    }
    show(0);
    setInterval(function(){
      idx = (idx+1)%quotes.length;
      show(idx);
    },4000);
  })();

  // Badges with tooltips
  (function(){
    var badges = document.querySelectorAll('#credBadges .badge');
    badges.forEach(function(b){
      var tipText = b.getAttribute('data-tip');
      if(!tipText) return;
      var tip = document.createElement('div');
      tip.className = 'tip';
      tip.textContent = tipText;
      b.appendChild(tip);
      b.addEventListener('mouseenter',function(){ b.setAttribute('data-show-tip','true'); });
      b.addEventListener('mouseleave',function(){ b.setAttribute('data-show-tip','false'); });
      b.addEventListener('focus',function(){ b.setAttribute('data-show-tip','true'); });
      b.addEventListener('blur',function(){ b.setAttribute('data-show-tip','false'); });
    });
  })();

  // Pricing comparator (monthly vs package) with animated numbers
  (function(){
    var toggle = document.getElementById('billingToggle');
    var nums = document.querySelectorAll('.price-amount .num');
    function animateTo(el, target){
      var start = parseInt(el.textContent,10) || 0;
      var end = parseInt(target,10);
      var duration = 420;
      var startTime = performance.now();
      function step(t){
        var p = Math.min(1,(t-startTime)/duration);
        var val = Math.round(start + (end-start)*p);
        el.textContent = val;
        if(p<1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    function updatePrices(usePackage){
      document.querySelectorAll('.price-amount').forEach(function(pa){
        var monthly = pa.getAttribute('data-monthly');
        var pack = pa.getAttribute('data-package');
        var target = usePackage ? pack : monthly;
        var displayEl = pa.querySelector('.num');
        animateTo(displayEl, target);
      });
    }
    if(toggle){
      toggle.addEventListener('change',function(e){
        updatePrices(e.target.checked);
      });
      // initial sync: unchecked = monthly
      updatePrices(false);
    }
  })();

  // Accessibility: set current year
  var y = document.getElementById('year'); if(y) y.textContent = new Date().getFullYear();

});
"} 
